{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\' create or replace table snitch_db.maplemonk.offline_hourly_sales_eoss as WITH current_cutoff AS ( SELECT DATE_TRUNC(\'day\', CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', current_timestamp))::TIMESTAMP_NTZ AS today_date, CONVERT_TIMEZONE(\'America/Los_Angeles\', \'Asia/Kolkata\', CURRENT_TIMESTAMP::TIMESTAMP_NTZ ) cutoff_time ), eoss_skus AS ( SELECT DISTINCT UPPER(sku_group) AS sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_EOSS WHERE sku_status = \'EOSS\' ), store_info AS ( SELECT DISTINCT branch_code, state, UPPER(am) AS am FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), sales AS ( SELECT si.state, si.am, s.marketplace_mapped AS store, s.branch_code, COALESCE(SUM(CASE WHEN e.sku_group IS NULL THEN s.selling_price ELSE 0 END), 0) AS normal_sales, COALESCE(SUM(CASE WHEN e.sku_group IS NOT NULL THEN s.selling_price ELSE 0 END), 0) AS eoss_sales, COALESCE(SUM(CASE WHEN e.sku_group IS NULL THEN s.mrp * s.suborder_quantity ELSE 0 END), 0) AS normal_mrp, COALESCE(SUM(CASE WHEN e.sku_group IS NOT NULL THEN s.mrp * s.suborder_quantity ELSE 0 END), 0) AS eoss_mrp, COUNT(DISTINCT s.order_id) AS today_bills, COALESCE( SUM( CASE WHEN s.sku_group NOT LIKE \'CB%\' THEN s.shipping_quantity ELSE 0 END ), 0 ) AS today_units FROM SNITCH_DB.MAPLEMONK.STORE_fact_items_offline s JOIN current_cutoff c ON s.order_timestamp >= c.today_date AND s.order_timestamp < c.cutoff_time LEFT JOIN eoss_skus e ON UPPER(s.sku_group) = e.sku_group LEFT JOIN store_info si ON si.branch_code = s.branch_code WHERE LOWER(s.order_status) LIKE \'%process%\' AND s.doc_prefix NOT IN (\'OMS\',\'QCOM\') AND s.marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\', \'SNITCH - WH - SR\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA 2\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - B2B\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - SNITCH X\', \'SNITCH - WH - NORTH\' ) GROUP BY si.state, si.am, s.marketplace_mapped, s.branch_code ), returns AS ( SELECT si.state, si.am, r.marketplace_mapped AS store, COALESCE(SUM(CASE WHEN e.sku_group IS NULL THEN r.selling_price ELSE 0 END), 0) AS normal_returns, COALESCE(SUM(CASE WHEN e.sku_group IS NOT NULL THEN r.selling_price ELSE 0 END), 0) AS eoss_returns FROM SNITCH_DB.MAPLEMONK.store_returns_fact_items r JOIN current_cutoff c ON r.order_timestamp >= c.today_date AND r.order_timestamp < c.cutoff_time LEFT JOIN eoss_skus e ON UPPER(r.sku_group) = e.sku_group LEFT JOIN store_info si ON si.branch_code = r.branch_code GROUP BY si.state, si.am, r.marketplace_mapped ), targets AS ( SELECT COALESCE( TRY_TO_DATE(\"Date \", \'DD/MM/YYYY\'), TRY_TO_DATE(\"Date \", \'DD-MM-YYYY\') ) AS date, REPLACE(\"Target \", \',\', \'\')::INT AS day_target, \"Branch \" AS branch_code FROM SNITCH_DB.MAPLEMONK.MTD_TARGET ) SELECT s.state, s.am, s.store, ROUND(s.normal_sales - COALESCE(r.normal_returns, 0), 0) AS net_normal_sales, ROUND(s.eoss_sales - COALESCE(r.eoss_returns, 0), 0) AS net_eoss_sales, ROUND( (s.normal_sales + s.eoss_sales) - COALESCE(r.normal_returns, 0) - COALESCE(r.eoss_returns, 0), 0 ) AS net_sales, CASE WHEN s.today_bills = 0 THEN 0 ELSE ROUND(s.today_units / s.today_bills, 2) END AS today_upt, CASE WHEN COALESCE(t.day_target, 0) = 0 THEN 0 ELSE ROUND( ( (s.normal_sales + s.eoss_sales) - COALESCE(r.normal_returns, 0) - COALESCE(r.eoss_returns, 0) ) / t.day_target, 2 ) END AS daily_achievement_pct, COALESCE(t.day_target, 0) AS day_target, CASE WHEN s.normal_mrp = 0 THEN 0 ELSE ROUND((s.normal_mrp - s.normal_sales) / s.normal_mrp, 2) END AS normal_discount_pct, CASE WHEN s.eoss_mrp = 0 THEN 0 ELSE ROUND((s.eoss_mrp - s.eoss_sales) / s.eoss_mrp, 2) END AS eoss_discount_pct, CASE WHEN (s.normal_mrp + s.eoss_mrp) = 0 THEN 0 ELSE ROUND( ( (s.normal_mrp + s.eoss_mrp) - (s.normal_sales + s.eoss_sales) ) / (s.normal_mrp + s.eoss_mrp), 2 ) END AS overall_discount_pct, FROM sales s LEFT JOIN returns r ON s.state = r.state AND s.am = r.am AND s.store = r.store LEFT JOIN targets t ON s.branch_code = t.branch_code AND t.date = current_date ORDER BY net_sales desc, s.state, s.am, s.store ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            